from math import sqrt
queries = {
    "商品名": {"a", "b"},
    "通用名": {"a", "b"},
    "剂型": {"c", "d"},
    "版本": {"d", "e"},
    "说明书": {"e", "f"},
}
counts = {"a":9, "b":8, "c":7, "d":6, "e":5, "f":3}
weights = {key: sqrt(n) for key, n in counts.items()}
selected, covered = [], set()
for _ in range(3):
    scores = {
        name: sum(weights[k] for k in docs - covered)
        for name, docs in queries.items()
        if name not in selected
    }
    winner = max(scores, key=scores.get)
    selected.append(winner)
    covered |= queries[winner]
assert selected == ["商品名", "剂型", "说明书"]
assert len(covered) == 6
assert "通用名" not in selected
print(selected, len(covered))
